#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> vec(n);
    for (int &x : vec) cin >> x;

    sort(vec.begin(), vec.end());

    int ans = INT_MAX;

    for (int i = 1; i < n - 1; ++i) {
        int maxGap = 0;

        for (int j = 1; j < n; ++j) {
            if (j == i) continue;
            int previous = (j - 1 == i ? j - 2 : j - 1);
            maxGap = max(maxGap, vec[j] - vec[previous]);
        }

        ans = min(ans, maxGap);
    }

    cout << ans << '\n';
    return 0;
}

