#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> a(n);
    for (long long &x : a) cin >> x;

    sort(a.begin(), a.end());

    if (n <= 2) {
        cout << 0 << '\n';
        return 0;
    }

    long long answer = LLONG_MAX;

    for (int removed = 1; removed < n - 1; ++removed) {
        long long maximumGap = 0;
        int previous = 0;

        for (int i = 1; i < n; ++i) {
            if (i == removed) continue;
            maximumGap = max(maximumGap, a[i] - a[previous]);
            previous = i;
        }

        answer = min(answer, maximumGap);
    }

    cout << answer << '\n';
    return 0;
}

